parameters.jsCode:
const trigger = $('Sub-Workflow Trigger').first().json;
const payload = trigger.body ? trigger.body : trigger;
const aiResp = $input.first().json;

let aiResult = {};
let rawText = '';
if (aiResp && aiResp.output) {
  rawText = String(aiResp.output);
} else if (aiResp && aiResp.candidates && aiResp.candidates[0]?.content?.parts?.[0]?.text) {
  rawText = aiResp.candidates[0].content.parts[0].text;
}

if (rawText) {
  try {
    const clean = rawText.replace(/```json/g, '').replace(/```/g, '').trim();
    aiResult = JSON.parse(clean);
  } catch(e) {}
}

const subject = String(payload.subject || '').toLowerCase();
const body = String(payload.body || payload.clean_body || '').toLowerCase();
const text = subject + ' ' + body;

// Nhận diện theo từ khóa ưu tiên (hỗ trợ cả có dấu và không dấu)
const isP1Keyword = /(sập|sap|504|500|outage|down|sự cố|su co|khẩn cấp|khan cap|quá tải|qua tai|không thể truy cập|khong the truy cap|tê liệt|te liet|chết server|chet server)/i.test(text);
const isTechnical = isP1Keyword || /(lỗi|loi|bug|crash|server|máy chủ|may chu|database|kết nối|ket noi|api|kỹ thuật|ky thuat|mạng|mang|gateway)/i.test(text);
const isSales = /(báo giá|bao gia|mua hàng|mua hang|hợp đồng|hop dong|tư vấn|tu van|ngân sách|ngan sach|chi phí phần mềm|deal|crm|lead)/i.test(text);
const isFinance = /(hóa đơn|hoa don|invoice|vat|thuế|thue|thanh toán|thanh toan|chuyển khoản|chuyen khoan)/i.test(text);

let dept = String(aiResult.department || '').toUpperCase();
let priority = String(aiResult.priority || '').toUpperCase();

if (isP1Keyword) {
  dept = 'TECH';
  priority = 'P1 - Critical';
} else if (isTechnical) {
  dept = 'TECH';
  if (!priority.includes('P1')) priority = 'P2 - High';
} else if (isSales) {
  dept = 'SALES';
  priority = 'P2 - High';
} else if (isFinance) {
  dept = 'FINANCE';
  priority = 'P3 - Medium';
} else if (!dept || dept === 'GENERAL') {
  dept = 'GENERAL';
  priority = 'P4 - Low';
}

// Chuẩn hóa Department
const categoryMap = { TECH: 'Technical', SALES: 'Sales', FINANCE: 'Finance', GENERAL: 'General' };
const category = categoryMap[dept] || 'General';

// Chuẩn hóa Priority P1-P4
if (priority.includes('P1')) priority = 'P1 - Critical';
else if (priority.includes('P2')) priority = 'P2 - High';
else if (priority.includes('P3')) priority = 'P3 - Medium';
else priority = 'P4 - Low';

let sentiment = 'neutral';
if (priority.includes('P1')) sentiment = 'urgent';
else if (dept === 'SALES') sentiment = 'positive';
else if (dept === 'TECH') sentiment = 'negative';

const confidence = 95;
const confidenceScore = 0.95;
const urgencyReason = aiResult.urgency_reason || (priority.includes('P1') ? 'Sự cố P1 đe dọa gián đoạn dịch vụ toàn hệ thống' : 'AI Triage Auto Processed');

// Tính luôn SLA Deadline chuẩn xác
let slaHours = 24;
if (priority.includes('P1')) slaHours = 1;
else if (priority.includes('P2')) slaHours = 4;
else if (priority.includes('P3')) slaHours = 24;
else if (priority.includes('P4')) slaHours = 48;

const now = new Date();
const slaDueAt = new Date(now.getTime() + slaHours * 60 * 60 * 1000);
const formattedDeadline = slaDueAt.toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh', hour12: false });
const trackingCode = `REQ-${Date.now().toString(36).toUpperCase()}`;

return [{
  json: {
    ...payload,
    department: dept,
    department_code: dept,
    category: category,
    priority: priority,
    sentiment: sentiment,
    confidence: confidence,
    confidence_score: confidenceScore,
    urgency_reason: urgencyReason,
    sla_hours: slaHours,
    sla_due_at: slaDueAt.toISOString(),
    sla_deadline: slaDueAt.toISOString(),
    formatted_deadline: formattedDeadline,
    tracking_code: trackingCode
  }
}];

